#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
run_wizard() {

TOTAL_STAGES=4

# Developer portal setup for iCloud sync of the Library (#139, ADR-0022).
# The container is shared with the Watch App later (#140), so it is named
# after the app, not the phone.
REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
APP_DIR="$REPO_DIR/app"
BUNDLE_ID="com.season42.app"
CONTAINER_ID="iCloud.$BUNDLE_ID"
LOCAL_XCCONFIG="$APP_DIR/Config/Local.xcconfig"
export DEVELOPER_DIR="${DEVELOPER_DIR:-/Applications/Xcode.app/Contents/Developer}"

banner "iCloud setup for Season42: $CONTAINER_ID"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: team and Xcode account"
team=$(sed -nE 's/^[[:space:]]*DEVELOPMENT_TEAM[[:space:]]*=[[:space:]]*([A-Z0-9]+).*/\1/p' "$LOCAL_XCCONFIG" 2>/dev/null | tail -n1)
if [[ -z "$team" ]]; then
  warn "No DEVELOPMENT_TEAM in $LOCAL_XCCONFIG."
  open_url "https://developer.apple.com/account#MembershipDetailsCard"
  step "Membership details → copy the Team ID (10 characters)."
  ask DEVELOPMENT_TEAM "Paste your Team ID:"
  [[ -f "$LOCAL_XCCONFIG" ]] || cp "$APP_DIR/Config/Local.xcconfig.example" "$LOCAL_XCCONFIG"
  if grep -qE '^[[:space:]]*DEVELOPMENT_TEAM' "$LOCAL_XCCONFIG"; then
    sed -i '' -E "s/^[[:space:]]*DEVELOPMENT_TEAM.*/DEVELOPMENT_TEAM = $DEVELOPMENT_TEAM/" "$LOCAL_XCCONFIG"
  else
    printf 'DEVELOPMENT_TEAM = %s\n' "$DEVELOPMENT_TEAM" >> "$LOCAL_XCCONFIG"
  fi
  printf '  %s✓ wrote%s DEVELOPMENT_TEAM → %s\n' "$GREEN" "$RESET" "$LOCAL_XCCONFIG"
  team="$DEVELOPMENT_TEAM"
else
  say "✓ team $team, from app/Config/Local.xcconfig"
fi
say ""
say "Device builds sign with the Apple ID that Xcode knows about."
step "Xcode → Settings → Accounts: check the Apple ID for team $team is listed and isn't asking you to sign in again."
pause "Press Enter once Xcode has your developer account"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Developer portal: register the iCloud container"
say "This is the real app's container. The iPhone app and, later, the Watch App both use it."
warn "Container IDs can't be deleted, renamed or reused. Check the spelling before you click Register."
open_url "https://developer.apple.com/account/resources/identifiers/list/cloudContainer"
step "Identifiers, filtered to iCloud Containers. If $CONTAINER_ID is listed, skip to the next stage."
step "Otherwise click the blue + next to Identifiers → iCloud Containers → Continue."
step "Description: Season42"
step "Identifier: $CONTAINER_ID   (if the field already shows 'iCloud.', type only $BUNDLE_ID)"
if confirm "Identifier typed exactly as $CONTAINER_ID? (no means skip registering for now)"; then
  step "Continue → Register."
  pause "Press Enter once $CONTAINER_ID is in the list"
else
  SKIPPED+=("Register the iCloud container $CONTAINER_ID")
  warn "Skipped. Re-run the wizard when you're ready."
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Developer portal: App ID with iCloud and Push"
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "Open the App ID for $BUNDLE_ID. Xcode-made ones are named like 'XC com season42 app'."
step "If it's missing: + → App IDs → App → Continue → Explicit Bundle ID: $BUNDLE_ID, Description: Season42."
step "Under Capabilities, tick iCloud and choose 'Include CloudKit support'."
step "Tick Push Notifications. No certificate is needed: CloudKit sends its own pushes."
step "Save (or Continue → Register for a new App ID)."
step "Open the App ID again → iCloud row → Edit/Configure → tick $CONTAINER_ID → Continue → Save."
note "Changing capabilities invalidates this App ID's existing profiles. The next device build fetches new ones."
pause "Press Enter once the App ID has iCloud (with $CONTAINER_ID) and Push"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Check: CloudKit Console and a signed build"
open_url "https://icloud.developer.apple.com/dashboard/"
step "On the Console's home page, click CloudKit Database."
step "Use the container menu at the top left to pick $CONTAINER_ID, with the environment set to Development."
say "Done when the header reads '$CONTAINER_ID › Development'. Nothing in the left menu is needed yet."
note "Not in the menu? Stage 2 didn't register it, or the portal hasn't caught up yet: wait a few minutes and reload."
note "Schema → Record Types and Records stay empty until a #139 build with sync on uploads the Library. That's expected."
note "Later, to see records: Records → Private Database → zone com.apple.coredata.cloudkit.zone, signed in as the syncing Apple ID."
warn "Never click 'Deploy Schema Changes to Production' here. After that the schema can only grow (ADR-0022). It's a separate step, not part of #139."
say ""
entitlements=$(grep -rl --include='*.entitlements' "$CONTAINER_ID" "$APP_DIR/Season42" 2>/dev/null | head -n1 || true)
if [[ -z "$entitlements" ]]; then
  note "The app has no entitlements naming $CONTAINER_ID yet, which is expected: #139 adds them."
  note "The first device build in #139 (with -allowProvisioningUpdates) is the check that this portal setup is right."
  pause "Press Enter to finish"
elif confirm "Run a signed device build now to check the portal setup?"; then
  say "Building for a generic iOS device, so Xcode fetches a development profile with iCloud and Push…"
  if xcodebuild -project "$APP_DIR/Season42.xcodeproj" -scheme Season42 -configuration Debug \
       -destination 'generic/platform=iOS' -allowProvisioningUpdates build -quiet; then
    say "✓ signed: the profile has the iCloud container and Push."
  else
    warn "Build failed. Usual causes: Xcode isn't signed in (stage 1), or the App ID lacks iCloud/Push or the ticked container (stage 3)."
    SKIPPED+=("A signed device build that passes")
  fi
  pause "Press Enter to finish"
fi

finish
say "Before this build goes on your iPhone: take a Library Export from Settings."
say "Install it from Xcode, not TestFlight, until the schema is promoted to production."
printf '\n'
}

run_wizard "$@"; exit
